-- ============================================
-- LUMA — Thème 4 : MOYEN 3/3 x4 — S'orienter dans un aéroport inconnu
-- ============================================


update scenarios set content = '{"characters": {"staff": "le personnel de l''aéroport", "passenger": "un passager", "gate_agent": "l''agent de porte"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You land in a huge unfamiliar airport with only 40 minutes to your connecting gate.)", "text_fr": "(Vous atterrissez dans un immense aéroport inconnu avec seulement 40 minutes pour votre porte de correspondance.)", "choices": [{"text": "(Look for an information desk immediately.)", "text_fr": "(Cherche un comptoir d''informations immédiatement.)", "next": "n2"}, {"text": "(Check the departure boards yourself first.)", "text_fr": "(Vérifie d''abord les panneaux de départ toi-même.)", "next": "n2b"}]}, "n2": {"speaker": "staff", "text": "Hi, can I help you find something?", "text_fr": "Bonjour, je peux vous aider à trouver quelque chose ?", "choices": [{"text": "Yes, I need to get to gate C34 quickly, my connection is tight.", "text_fr": "Oui, je dois aller à la porte C34 rapidement, ma correspondance est serrée.", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(The boards are confusing and in a different layout than you''re used to.)", "text_fr": "(Les panneaux sont confus et dans une disposition différente de celle à laquelle vous êtes habitué.)", "choices": [{"text": "(Ask a staff member for help instead.)", "text_fr": "(Demande de l''aide à un membre du personnel à la place.)", "next": "n2"}]}, "n3": {"speaker": "staff", "text": "That''s in Terminal C — you''ll need to take the shuttle train from here.", "text_fr": "C''est dans le Terminal C — vous devrez prendre la navette depuis ici.", "choices": [{"text": "Where''s the shuttle train located?", "text_fr": "Où se trouve la navette ?", "next": "n4"}, {"text": "Is there a faster way, since I''m short on time?", "text_fr": "Il y a un moyen plus rapide, car je manque de temps ?", "next": "n4b"}]}, "n4": {"speaker": "staff", "text": "Just follow the signs for ''Inter-terminal Transit'' down this hallway.", "text_fr": "Suivez juste les panneaux ''Transit inter-terminaux'' dans ce couloir.", "choices": [{"text": "Thank you so much, I''ll hurry there now.", "text_fr": "Merci beaucoup, je m''y dépêche maintenant.", "next": "n5"}]}, "n4b": {"speaker": "staff", "text": "The shuttle is actually your fastest option, it runs every five minutes.", "text_fr": "La navette est en fait votre option la plus rapide, elle passe toutes les cinq minutes.", "choices": [{"text": "Perfect, I''ll head there right away.", "text_fr": "Parfait, j''y vais tout de suite.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(You find the shuttle and board just as the doors are closing.)", "text_fr": "(Vous trouvez la navette et montez juste au moment où les portes se ferment.)", "choices": [{"text": "(Check your watch nervously during the ride.)", "text_fr": "(Vérifie ta montre nerveusement pendant le trajet.)", "next": "n6"}, {"text": "(Ask a fellow passenger if this is the right stop for Terminal C.)", "text_fr": "(Demande à un autre passager si c''est bien l''arrêt pour le Terminal C.)", "next": "n6"}]}, "n6": {"speaker": "passenger", "text": "Yeah, this goes straight to Terminal C, don''t worry.", "text_fr": "Ouais, ça va direct au Terminal C, t''inquiète.", "choices": [{"text": "Thank you, that''s a relief to hear.", "text_fr": "Merci, ça soulage d''entendre ça.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(You arrive at Terminal C with 15 minutes to spare, and jog toward gate C34.)", "text_fr": "(Vous arrivez au Terminal C avec 15 minutes d''avance, et courez vers la porte C34.)", "choices": [{"text": "(Arrive breathless but just in time for boarding.)", "text_fr": "(Arrive essoufflé mais juste à temps pour l''embarquement.)", "next": "n8"}]}, "n8": {"speaker": "gate_agent", "text": "Just in time! We''re boarding now, welcome aboard.", "text_fr": "Juste à temps ! On embarque maintenant, bienvenue à bord.", "choices": [{"text": "(Catch your breath, relieved.) Thank you, that was close!", "text_fr": "(Reprends ton souffle, soulagé.) Merci, c''était juste !", "next": "end_madeit"}]}, "end_madeit": {"speaker": "gate_agent", "text": "You made it! Have a great flight.", "text_fr": "Vous avez réussi ! Bon vol.", "end": true, "ending_label": "Correspondance attrapée de justesse 🏃✈️"}}}'::jsonb, is_playable = true
where title = 'S''''orienter dans un aéroport inconnu'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
